    """Apply ("pct", basis_points) and ("off", cents) coupons one after another; the amount never drops below zero."""
    amount = subtotal
    for kind, value in coupons:
        if kind == "pct":
            amount -= div_round(amount * value, 10000)
        elif kind == "off":
            amount -= value
        else:
            raise ValueError(f"unknown coupon {kind!r}")
        amount = max(amount, 0)
    return amount


